//! Original Sys fields over complete CODE index plus selected CODE_MAPS source loans.
//! Generic DATA has no completion authority; the host requires both real EOF tokens.
use crate::{captured_api_pages as shared,captured_generator_budget::Budget,captured_raw_file::{Config,RawPolicyViews},captured_reactive_reads::Failure,reactive_raw_policy_pages::RawPolicyPages,lint::{Site,AllowUse}};
use std::{io,sync::Arc};
pub fn metadata()->&'static crate::lint::Meta{static META:std::sync::OnceLock<crate::lint::Meta>=std::sync::OnceLock::new();META.get_or_init(||crate::dm::sys::module_metadata(&crate::dm::sys::SysModule{name:crate::allow_registry_fields::sys_fields::SCOPE_MODULE_NAME,rules:crate::sys_fields_policy::RULES,..crate::dm::sys::SysModule::DEFAULT},crate::lint::ScanKind::Tree))}
pub struct FieldData{data:shared::ApiData}
impl FieldData{pub fn sites(&self)->&[Site]{self.data.sites()}pub fn source_text(&self)->&[String]{self.data.source_text()}pub fn allow_used(&self)->&[AllowUse]{self.data.allow_used()}pub fn allow_source_digest(&self,rel:&str)->Option<&[u8;20]>{self.data.allow_source_digest(rel)}}
pub(crate) fn record_rows(views:RawPolicyViews<'_>,found:Vec<(&'static str,usize)>,aliases:&[&str],alias_rules:&[&str],root:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<shared::ApiData,Failure>{record_rows_borrowed(&views,found,aliases,alias_rules,root,poll)}
pub(crate) fn record_rows_borrowed(views:&RawPolicyViews<'_>,found:Vec<(&'static str,usize)>,aliases:&[&str],alias_rules:&[&str],root:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<shared::ApiData,Failure>{record_rows_borrowed_with_patterns(views,found,aliases,alias_rules,root,poll,None)}
pub(crate) fn record_rows_with_patterns(views:RawPolicyViews<'_>,found:Vec<(&'static str,usize)>,aliases:&[&str],alias_rules:&[&str],root:&Budget,poll:&dyn Fn()->io::Result<()>,patterns:Option<&dyn crate::native_pattern::Provider>)->Result<shared::ApiData,Failure>{record_rows_borrowed_with_patterns(&views,found,aliases,alias_rules,root,poll,patterns)}
pub(crate) fn record_rows_borrowed_with_patterns(views:&RawPolicyViews<'_>,found:Vec<(&'static str,usize)>,aliases:&[&str],alias_rules:&[&str],root:&Budget,poll:&dyn Fn()->io::Result<()>,patterns:Option<&dyn crate::native_pattern::Provider>)->Result<shared::ApiData,Failure>{let file=views.source_file()?;let mut data=shared::empty();for(rule,line)in found{shared::checked(root,poll)?;let local=views.allocation_budget(root);let width=4usize.checked_add(rule.len()).ok_or("Sys fields ALLOW name overflow")?;local.charge(width.checked_mul(4).and_then(|n|n.checked_add(128)).ok_or("Sys fields ALLOW name overflow")?).map_err(|message|Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,message)))?;let mut name=format!("sys_{rule}");let raw=file.raw();let mut control=crate::captured_allow_annotations::PatternOperation{patterns,budget:local,poll};let mut kept=None;if line>=1&&line<=raw.num_lines(){if let Some(code)=crate::allow::keeps_with(raw.line(line),&name,&mut control)?{kept=Some((line,code));}}if kept.is_none()&&line>=2{let above=raw.line(line-1);if crate::util::py_lstrip(above).starts_with("//"){if let Some(code)=crate::allow::keeps_with(above,&name,&mut control)?{kept=Some((line-1,code));}}}
if kept.is_none()&&(alias_rules.is_empty()||alias_rules.contains(&rule)){for &alias in aliases{if line>=1&&line<=raw.num_lines(){if let Some(code)=crate::allow::keeps_with(raw.line(line),alias,&mut control)?{kept=Some((line,code));}}if kept.is_none()&&line>=2{let above=raw.line(line-1);if crate::util::py_lstrip(above).starts_with("//"){if let Some(code)=crate::allow::keeps_with(above,alias,&mut control)?{kept=Some((line-1,code));}}}if kept.is_some(){local.charge(alias.len().checked_mul(4).and_then(|n|n.checked_add(128)).ok_or("Sys alias name overflow")?).map_err(|message|Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,message)))?;name=alias.to_owned();break}}}
if let Some((at,code))=kept{let code=code.unwrap_or_default();let number=u32::try_from(at).map_err(|_|Failure::from("Sys fields ALLOW line exceeds wire coordinate"))?;if !data.allow_used.iter().any(|u|u.rel==file.rel&&u.line==number&&u.name==name&&u.code==code){shared::row(root,poll,&mut data.allow_used)?;data.allow_used.push(AllowUse{rel:shared::own(root,poll,&file.rel)?,line:number,name:shared::own(root,poll,&name)?,code:shared::own(root,poll,&code)?});}if !data.digests.contains_key(file.rel.as_str()){shared::node(root)?;data.digests.insert(shared::own(root,poll,&file.rel)?,crate::captured_raw_file::source_allow_digest(file));}continue}
shared::row(root,poll,&mut data.sites)?;shared::row(root,poll,&mut data.source_text)?;let source=file.line(line);let peak=source.len().checked_mul(4).and_then(|n|n.checked_add(256)).ok_or("Sys fields source line overflow")?;root.charge(peak).map_err(|message|Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,message)))?;let text=crate::util::normalize_ws(source);if text.capacity()>peak{root.deny();return Err(Failure::Operational(io::ErrorKind::OutOfMemory.into()))}data.source_text.push(text);data.sites.push(Site{rule:shared::own(root,poll,rule)?,rel:shared::own(root,poll,&file.rel)?,line:u32::try_from(line).map_err(|_|Failure::from("Sys fields line exceeds wire coordinate"))?,msg:String::new(),key:String::new(),ident:String::new()});}shared::checked(views.allocation_budget(root),poll)?;Ok(data)}
pub fn collect(pages:&dyn RawPolicyPages,config:&Config,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>)->Result<FieldData,Failure>{collect_using(pages,config,root,poll,None)}
pub fn collect_with_patterns(pages:&dyn RawPolicyPages,config:&Config,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>,patterns:&dyn crate::native_pattern::Provider)->Result<FieldData,Failure>{collect_using(pages,config,root,poll,Some(patterns))}
fn collect_using(pages:&dyn RawPolicyPages,config:&Config,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>,patterns:Option<&dyn crate::native_pattern::Provider>)->Result<FieldData,Failure>{shared::with_field_index_patterns(pages,root,poll,patterns,|index,budget|{let fields=if patterns.is_none(){Some(index.fields_named(crate::sys_fields_policy::CORE))}else{None};let mut rows=Vec::new();if !pages.for_each(&mut|relative,views|{shared::checked(budget,poll)?;if config.policy_path_exempt("sys/fields","sys",relative){return Ok(true)}let file=views.source_file()?;if file.rel!=relative{return Err("Sys fields selected original relative path differs".into())}let local=Budget::scoped_temporaries(root).map_err(|message|Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,message)))?;let native=patterns.map(|provider|crate::raw_fixture_policy::Fixture::scanned(&local,poll,provider,file)).transpose().map_err(pattern_failure)?;let legacy=crate::raw_fixture_policy::Fixture::legacy();let fixture=native.as_ref().unwrap_or(&legacy);let found=if native.is_some(){let actual=index.fields_named_with_fixture(crate::sys_fields_policy::CORE,fixture);if let Some(actual)=fixture.take_scan_failure(){return Err(pattern_failure(actual))}let actual=actual.map_err(Failure::Unsupported)?;crate::sys_fields_policy::scan_one_with_fixture(index,&actual,file,fixture)}else{crate::sys_fields_policy::scan_one(index,fields.as_ref().expect("actual legacy fields"),file)};if let Some(actual)=fixture.take_scan_failure(){return Err(pattern_failure(actual))}let data=record_rows_with_patterns(views,found,&[],&[],root,poll,patterns)?;shared::row(budget,poll,&mut rows)?;rows.push((shared::own(budget,poll,relative)?,data));Ok(true)})?{return Err("Sys fields selected source stopped before EOF".into())}budget.charge(rows.len().checked_mul(4*std::mem::size_of::<(String,shared::ApiData)>()).and_then(|n|n.checked_add(128)).ok_or("Sys fields sort overflow")?).map_err(|message|Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,message)))?;rows.sort_by(|a,b|a.0.cmp(&b.0));let mut data=shared::empty();for(_,row)in rows{shared::checked(budget,poll)?;shared::append(&mut data,row,root,poll)?;}drop(fields);Ok(FieldData{data})})}

fn pattern_failure(actual:crate::derived_selftest_policy::Failure)->Failure{match actual{crate::derived_selftest_policy::Failure::Operational(actual)=>Failure::Operational(actual),crate::derived_selftest_policy::Failure::Assertion(message)=>Failure::Unsupported(message)}}

#[cfg(test)]mod page_scratch_scope_controls{
 use super::*;use crate::{captured_raw_file::File,captured_raw_policy::Configuration};use std::cell::Cell;
 struct Pages{file:File,passes:Cell<usize>,fail_on:usize}
 impl RawPolicyPages for Pages{fn for_each(&self,visit:&mut dyn FnMut(&str,RawPolicyViews<'_>)->Result<bool,Failure>)->Result<bool,Failure>{let pass=self.passes.get()+1;self.passes.set(pass);if !self.file.with_policy_views(visit)?{return Ok(false)}if self.fail_on==pass{return Err(Failure::Operational(io::Error::from_raw_os_error(1450)))}Ok(true)}}
 fn pages(fail_on:usize)->Pages{let root=std::env::current_dir().unwrap().join("fields-page-scratch-data");let file=File::capture(&root,&root.join("code/probe.dm"),dm_preprocess::SourceText::from("/obj/machinery/probe
    var/on = 0
/obj/machinery/probe/proc/change()
    is_operational()
    on = 1
")).unwrap();Pages{file,passes:Cell::new(0),fail_on}}
 #[test]fn fields_index_and_selected_scan_use_same_root_siblings_and_preserve_real_finding(){
  let pages=pages(0);let root=Budget::new(1<<20).unwrap();let config=Config::capture(Configuration::ProvenMissing).unwrap();
  let data=collect(&pages,&config,&root,&||Ok(())).unwrap();assert_eq!(pages.passes.get(),2,"actual global field index and selected judgement both execute");assert!(data.sites().iter().any(|s|s.rule=="stat_helper"&&s.rel=="code/probe.dm"&&s.line==4),"scope repair cannot bypass the real original policy judgement");assert!(!root.denied());assert!(root.used()<1<<20);
 }
 #[test]fn fields_selected_provider_first_io_survives_scratch_and_fresh_fold_recovers(){
  let bad=pages(2);let config=Config::capture(Configuration::ProvenMissing).unwrap();let root=Budget::new(1<<20).unwrap();let error=collect(&bad,&config,&root,&||Ok(())).err().unwrap();assert!(matches!(error,Failure::Operational(ref e)if e.raw_os_error()==Some(1450)));assert_eq!(bad.passes.get(),2);
  let good=pages(0);let fresh=Budget::new(1<<20).unwrap();let data=collect(&good,&config,&fresh,&||Ok(())).unwrap();assert!(data.sites().iter().any(|s|s.rule=="stat_helper"&&s.line==4));assert_eq!(good.passes.get(),2);
 }
}
